import React, { useState, useEffect } from 'react';

const ProfileTab = ({ user, setUser, showSnackbarMessage }) => {
  const [newUsername, setNewUsername] = useState('');
  const [passwordConfirm, setPasswordConfirm] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordError, setPasswordError] = useState('');
  const [isUpdating, setIsUpdating] = useState(false);
  const [openConfirmUsername, setOpenConfirmUsername] = useState(false);
  const [openConfirmPassword, setOpenConfirmPassword] = useState(false);
  const [lastUpdated, setLastUpdated] = useState({});

  useEffect(() => {
    if (user?.workerID) {
      const storedTimestamps = localStorage.getItem(`lastUpdated_${user.workerID}`);
      if (storedTimestamps) {
        setLastUpdated(JSON.parse(storedTimestamps));
      }
    }
  }, [user]);

  const verifyPassword = async () => {
    if (!passwordConfirm) {
      setPasswordError('Please enter your password');
      return false;
    }

    try {
      const response = await fetch('http://localhost:8080/worker/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: user.username, password: passwordConfirm }),
      });

      if (response.ok) {
        return true;
      } else {
        setPasswordError('Incorrect password');
        return false;
      }
    } catch (error) {
      console.error('Error verifying password:', error);
      setPasswordError('Error verifying password');
      return false;
    }
  };

  const confirmUsernameUpdate = async () => {
    if (!user || !user.workerID) {
      showSnackbarMessage('User information is missing', 'error');
      return;
    }

    if (!await verifyPassword()) {
      return;
    }

    setIsUpdating(true);

    try {
      const response = await fetch(`http://localhost:8080/worker/updateWorker/${user.workerID}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: newUsername }),
      });

      if (response.ok) {
        const updatedUser = { ...user, username: newUsername };
        localStorage.setItem('user', JSON.stringify(updatedUser));
        localStorage.setItem('username', newUsername);

        const updatedTimestamps = {
          ...lastUpdated,
          username: new Date().toISOString()
        };
        localStorage.setItem(`lastUpdated_${user.workerID}`, JSON.stringify(updatedTimestamps));
        setLastUpdated(updatedTimestamps);

        setUser(updatedUser);
        setNewUsername('');
        showSnackbarMessage('Username updated successfully!');
      } else {
        showSnackbarMessage('Failed to update username', 'error');
      }
    } catch (err) {
      console.error('Error updating username:', err);
      showSnackbarMessage('Error updating username: ' + err.message, 'error');
    } finally {
      setIsUpdating(false);
      setOpenConfirmUsername(false);
    }
  };

  const confirmPasswordUpdate = async () => {
    if (!user || !user.workerID) {
      showSnackbarMessage('User information is missing', 'error');
      return;
    }

    if (!await verifyPassword()) {
      return;
    }

    if (newPassword !== confirmPassword) {
      showSnackbarMessage('Passwords do not match', 'error');
      return;
    }

    setIsUpdating(true);

    try {
      const response = await fetch(`http://localhost:8080/worker/updateWorker/${user.workerID}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password: newPassword }),
      });

      if (response.ok) {
        const updatedTimestamps = {
          ...lastUpdated,
          password: new Date().toISOString()
        };
        localStorage.setItem(`lastUpdated_${user.workerID}`, JSON.stringify(updatedTimestamps));
        setLastUpdated(updatedTimestamps);

        setNewPassword('');
        setConfirmPassword('');
        showSnackbarMessage('Password updated successfully!');
      } else {
        showSnackbarMessage('Failed to update password', 'error');
      }
    } catch (err) {
      console.error('Error updating password:', err);
      showSnackbarMessage('Error updating password: ' + err.message, 'error');
    } finally {
      setIsUpdating(false);
      setOpenConfirmPassword(false);
    }
  };

  return (
    <div className="profile-tab">
      <h2>Inspector Profile</h2>

      <div className="profile-section">
        <label>Current Username</label>
        <input type="text" value={user.username} disabled />
      </div>

      <div className="profile-section">
        <label>New Username</label>
        <input
          type="text"
          value={newUsername}
          onChange={(e) => setNewUsername(e.target.value)}
          placeholder="Enter new username"
        />
        <button onClick={() => setOpenConfirmUsername(true)} disabled={!newUsername || isUpdating}>
          Update Username
        </button>
      </div>

      <div className="profile-section">
        <label>New Password</label>
        <input
          type="password"
          value={newPassword}
          onChange={(e) => setNewPassword(e.target.value)}
          placeholder="Enter new password"
        />
        <label>Confirm New Password</label>
        <input
          type="password"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
          placeholder="Confirm new password"
        />
        <button onClick={() => setOpenConfirmPassword(true)} disabled={!newPassword || isUpdating}>
          Update Password
        </button>
      </div>

      {(openConfirmUsername || openConfirmPassword) && (
        <div className="confirm-section">
          <label>Confirm Current Password</label>
          <input
            type="password"
            value={passwordConfirm}
            onChange={(e) => {
              setPasswordConfirm(e.target.value);
              setPasswordError('');
            }}
            placeholder="Enter current password"
          />
          {passwordError && <p className="error-text">{passwordError}</p>}

          <button
            onClick={openConfirmUsername ? confirmUsernameUpdate : confirmPasswordUpdate}
            disabled={!passwordConfirm || isUpdating}
          >
            Confirm
          </button>
          <button
            onClick={() => {
              setOpenConfirmUsername(false);
              setOpenConfirmPassword(false);
              setPasswordConfirm('');
              setPasswordError('');
            }}
          >
            Cancel
          </button>
        </div>
      )}

      <div className="profile-section timestamps">
        <p><strong>Last username update:</strong> {lastUpdated.username || 'Never'}</p>
        <p><strong>Last password update:</strong> {lastUpdated.password || 'Never'}</p>
      </div>
    </div>
  );
};

export default ProfileTab;
